#!/usr/bin/env python3
"""Maintain flippass_app_api_symbols.h, the host symbols that plugins import.

FlipPass plugins may call host functions directly. The loader resolves each import
by name hash, first in the firmware API table and then in the host table built by
flippass_app_api.cpp. An import that neither table provides makes the plugin fail
to load on the device, which no build step reports, so run this after every build
that changes what a plugin calls:

    ufbt build && python extras/tools/flippass_app_api.py write && ufbt build
    python extras/tools/flippass_app_api.py check      # after a build; exits 1 if stale

`check` also fails when a host symbol's hash equals a firmware API symbol's hash,
or when a plugin imports a name that both the firmware API and the host define
(a host function shadowing a firmware one): the firmware table is searched first,
so such an import would silently bind to the firmware function.

Adapted from tools/gen_app_api.py in the chaffed/FlipPass fork (commit 282a30f).
"""
from __future__ import annotations

import argparse
import csv
import os
from pathlib import Path
import subprocess
import sys

REPO = Path(__file__).resolve().parents[2]
OUT = REPO / "flippass_app_api_symbols.h"
HEADER = [
    "// Generated by extras/tools/flippass_app_api.py from the plugins' imports. Do not edit by hand.",
    "// clang-format off",
]


def ufbt_home() -> Path:
    if os.environ.get("UFBT_HOME"):
        return Path(os.environ["UFBT_HOME"])
    for candidate in (Path.home() / ".ufbt", REPO / ".ufbt"):
        if (candidate / "build").is_dir():
            return candidate
    return Path.home() / ".ufbt"


def find_nm(home: Path) -> Path:
    names = ("arm-none-eabi-nm.exe", "arm-none-eabi-nm")
    for base in [
        home / "toolchain" / "current" / "bin",
        *sorted((home / "toolchain").glob("*/bin")),
    ]:
        for name in names:
            if (base / name).exists():
                return base / name
    sys.exit(
        f"arm-none-eabi-nm not found under {home / 'toolchain'}; run `ufbt update` first."
    )


def elf_gnu_hash(name: str) -> int:
    h = 0x1505
    for byte in name.encode():
        h = (h * 33 + byte) & 0xFFFFFFFF
    return h


def firmware_symbols(api_csv: Path) -> set[str]:
    with api_csv.open(encoding="utf-8") as handle:
        return {
            row["name"]
            for row in csv.DictReader(handle)
            if row["entry"] in ("Function", "Variable") and row["status"] == "+"
        }


def nm_names(nm: Path, elf: Path, *flags: str) -> set[str]:
    out = subprocess.run(
        [str(nm), *flags, str(elf)], check=True, capture_output=True, text=True
    )
    return {line.split()[-1] for line in out.stdout.splitlines() if line.strip()}


def render(names: set[str]) -> str:
    return (
        "\n".join(HEADER + [f"FLIPPASS_APP_API({name})" for name in sorted(names)])
        + "\n"
    )


def main() -> int:
    parser = argparse.ArgumentParser(
        description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter
    )
    parser.add_argument("action", choices=("write", "check"))
    parser.add_argument(
        "--build-dir",
        type=Path,
        help="uFBT build directory (default: $UFBT_HOME/build)",
    )
    parser.add_argument(
        "--api-csv", type=Path, help="firmware api_symbols.csv of the SDK in use"
    )
    args = parser.parse_args()

    home = ufbt_home()
    build = args.build_dir or home / "build"
    api_csv = (
        args.api_csv
        or home
        / "current"
        / "sdk_headers"
        / "f7_sdk"
        / "targets"
        / "f7"
        / "api_symbols.csv"
    )
    nm = find_nm(home)
    plugins = sorted(build.glob("flippass_*.fal"))
    host_elf = build / "flippass_d.elf"
    if not plugins or not api_csv.exists():
        sys.exit(
            f"No built plugins in {build} or no {api_csv}; run `ufbt build` first."
        )

    firmware = firmware_symbols(api_csv)
    needed: dict[str, list[str]] = {}
    for fal in plugins:
        for name in sorted(nm_names(nm, fal, "-u") - firmware):
            needed.setdefault(name, []).append(fal.stem)
    names = set(needed)

    problems = []
    if host_elf.exists():
        host_globals = nm_names(nm, host_elf, "-g", "--defined-only")
        for fal in plugins:
            for name in sorted((nm_names(nm, fal, "-u") & firmware & host_globals)):
                if not name.startswith("__aeabi_"):
                    problems.append(
                        f"{fal.stem} imports {name}, which the host redefines; "
                        "it would bind to the firmware's version"
                    )
    fw_hashes = {elf_gnu_hash(name): name for name in firmware}
    for name in sorted(names):
        clash = fw_hashes.get(elf_gnu_hash(name))
        if clash is not None:
            problems.append(
                f"hash of host symbol {name} equals firmware symbol {clash}"
            )
    if host_elf.exists():
        host_defined = nm_names(nm, host_elf, "-g", "--defined-only")
        missing = sorted(names - host_defined)
        if missing and args.action == "check":
            problems += [
                f"{n} (imported by {', '.join(needed[n])}) is not defined by the host"
                for n in missing
            ]
        elif missing:
            print(
                f"note: {len(missing)} symbols are not in the host yet; rebuild to link them in"
            )

    text = render(names)
    if args.action == "write":
        OUT.write_text(text, encoding="utf-8", newline="\n")
        print(f"{OUT.name}: {len(names)} host symbols for {len(plugins)} plugins")
    else:
        current = (
            OUT.read_text(encoding="utf-8").replace("\r\n", "\n")
            if OUT.exists()
            else ""
        )
        if current != text:
            listed = {
                line[len("FLIPPASS_APP_API(") : -1]
                for line in current.splitlines()
                if line.startswith("FLIPPASS_APP_API(")
            }
            problems += [
                f"missing from {OUT.name}: {n}" for n in sorted(names - listed)
            ]
            problems += [
                f"no longer imported, remove from {OUT.name}: {n}"
                for n in sorted(listed - names)
            ]
            if not (names ^ listed):
                problems.append(f"{OUT.name} is not in canonical form; run `write`")
    for problem in problems:
        print(f"error: {problem}", file=sys.stderr)
    if not problems and args.action == "check":
        print(
            f"{OUT.name} is current: {len(names)} host symbols for {len(plugins)} plugins"
        )
    return 1 if problems else 0


if __name__ == "__main__":
    raise SystemExit(main())
